  `name` varchar(100) NOT NULL COMMENT 'VD: Màu sắc',
  `attribute_key` varchar(50) NOT NULL COMMENT 'color, size',
  `type` enum('text','select','color','size') DEFAULT 'text',
  `attribute_values` text DEFAULT NULL COMMENT 'JSON Array values',
  `sort_order` int(11) DEFAULT 0,
  `status` enum('active','inactive') DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Danh sách thuộc tính';

