  `variant_id` bigint(20) UNSIGNED DEFAULT NULL,
  `branch_id` bigint(20) UNSIGNED NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0 COMMENT 'Số lượng tồn',
  `available_quantity` int(11) NOT NULL DEFAULT 0 COMMENT 'Có thể bán',
  `reserved_quantity` int(11) DEFAULT 0 COMMENT 'Đã đặt',
  `min_alert` int(11) DEFAULT NULL COMMENT 'Cảnh báo tối thiểu',
  `max_alert` int(11) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL COMMENT 'Vị trí trong kho',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tồn kho theo chi nhánh';

