  `branch_id` bigint(20) UNSIGNED NOT NULL,
  `stock_quantity` int(11) DEFAULT 0 COMMENT 'Số lượng tồn',
  `alert_stock` int(11) DEFAULT 10 COMMENT 'Ngưỡng cảnh báo',
  `reserved_stock` int(11) DEFAULT 0 COMMENT 'Hàng đang giữ',
  `available_stock` int(11) DEFAULT 0 COMMENT 'Có thể bán',
  `expiry_days` int(11) DEFAULT NULL COMMENT 'Dự kiến hết hàng (ngày)',
  `last_stock_date` datetime DEFAULT NULL COMMENT 'Lần cập nhật tồn cuối',
  `status` enum('in_stock','low_stock','out_of_stock') DEFAULT 'in_stock',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tồn kho theo từng chi nhánh';

