--
-- Cấu trúc bảng cho bảng `returns`
--

CREATE TABLE `returns` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `return_number` varchar(50) NOT NULL COMMENT 'Số phiếu trả hàng',
  `order_id` bigint(20) UNSIGNED NOT NULL,
  `customer_id` bigint(20) UNSIGNED NOT NULL,
  `branch_id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `type` enum('full','partial') DEFAULT 'partial' COMMENT 'Trả toàn bộ/một phần',
  `reason` enum('defective','wrong_item','not_satisfied','other') NOT NULL COMMENT 'Lý do trả hàng',
  `reason_detail` text DEFAULT NULL COMMENT 'Chi tiết lý do',
  `return_date` datetime NOT NULL COMMENT 'Ngày trả hàng',
  `return_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Tổng tiền trả',
  `refund_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Số tiền hoàn',
  `refund_method` enum('cash','bank_transfer','store_credit') DEFAULT NULL COMMENT 'Phương thức hoàn tiền',
  `status` enum('pending','approved','rejected','completed') DEFAULT 'pending',
  `approved_by` bigint(20) UNSIGNED DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

