  `product_id` bigint(20) UNSIGNED NOT NULL,
  `quantity` int(11) NOT NULL COMMENT 'Số lượng trả',
  `unit_price` decimal(15,2) NOT NULL COMMENT 'Đơn giá',
  `total_amount` decimal(15,2) NOT NULL COMMENT 'Thành tiền',
  `condition` enum('new','used','damaged') NOT NULL COMMENT 'Tình trạng hàng',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

