-- Cấu trúc bảng cho bảng `sales_orders`
--

CREATE TABLE `sales_orders` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `order_number` varchar(50) NOT NULL COMMENT 'Số đơn hàng',
  `customer_id` bigint(20) UNSIGNED NOT NULL,
  `branch_id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT 'Nhân viên bán',
  `status` enum('draft','pending','confirmed','processing','completed','cancelled') DEFAULT 'draft' COMMENT 'Trạng thái',
  `order_date` datetime NOT NULL COMMENT 'Ngày đặt hàng',
  `subtotal` decimal(15,2) DEFAULT 0.00 COMMENT 'Tổng trước thuế/giảm giá',
  `discount_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Giảm giá',
  `tax_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Thuế',
  `shipping_fee` decimal(15,2) DEFAULT 0.00 COMMENT 'Phí vận chuyển',
  `total_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Tổng tiền',
  `paid_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Đã thanh toán',
  `payment_status` enum('unpaid','partial','paid','refunded') DEFAULT 'unpaid' COMMENT 'Trạng thái thanh toán',
  `payment_method` enum('cash','bank_transfer','card','ewallet','cod') DEFAULT NULL COMMENT 'Phương thức thanh toán',
  `shipping_address` text DEFAULT NULL COMMENT 'Địa chỉ giao hàng',
  `notes` text DEFAULT NULL COMMENT 'Ghi chú',
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu bổ sung'
) ;

