--
-- Cấu trúc bảng cho bảng `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `username` varchar(100) NOT NULL COMMENT 'Tên đăng nhập',
  `email` varchar(255) NOT NULL COMMENT 'Email',
  `password` varchar(255) NOT NULL COMMENT 'Mật khẩu',
  `full_name` varchar(255) DEFAULT NULL COMMENT 'Họ và tên',
  `phone` varchar(20) DEFAULT NULL COMMENT 'Số điện thoại',
  `avatar` varchar(255) DEFAULT NULL COMMENT 'Ảnh đại diện',
  `branch_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Chi nhánh',
  `status` enum('active','inactive','suspended') DEFAULT 'active' COMMENT 'Trạng thái',
  `last_login_at` timestamp NULL DEFAULT NULL COMMENT 'Lần đăng nhập cuối',
  `last_login_ip` varchar(45) DEFAULT NULL COMMENT 'IP đăng nhập cuối',
  `remember_token` varchar(100) DEFAULT NULL,
  `two_factor_secret` varchar(255) DEFAULT NULL COMMENT 'Secret key cho 2FA',
  `two_factor_enabled` tinyint(1) DEFAULT 0 COMMENT '2FA có được bật',
  `password_changed_at` timestamp NULL DEFAULT NULL COMMENT 'Lần đổi mật khẩu cuối',
  `failed_login_attempts` int(11) DEFAULT 0 COMMENT 'Số lần đăng nhập sai',
  `account_locked_until` timestamp NULL DEFAULT NULL COMMENT 'Khóa tài khoản đến',
  `timezone` varchar(50) DEFAULT 'Asia/Ho_Chi_Minh' COMMENT 'Múi giờ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

